catalog_script_client.script:
function onSubmit() {

    if (!g_form.ajaxComplete) {
		ajaxCall();
        return false;
    }
}

function ajaxCall(){
	var rewardType = g_form.getValue('reward_type');
    var amount = g_form.getValue('amount');

    var rewardUtilsGa = new GlideAjax('x_1921751_employ_0.RewardUtils');
    rewardUtilsGa.addParam('sysparm_name', 'getRewardTypeDetails');
    rewardUtilsGa.addParam('sysparm_reward_id', rewardType);
    rewardUtilsGa.getXMLAnswer(function(answer) {
        if (answer != "Not Found") {
            var response = JSON.parse(answer);
            if (amount < response.minValue || amount > response.maxValue) {
                g_form.addErrorMessage("Reward Amount is not within range. Min Value = " + response.minValue + " and Max Value = " + response.maxValue);

                g_form.ajaxComplete = true;
            }
        }
    });
}
